from __future__ import annotations

from fractions import Fraction
import json
from pathlib import Path

from pylibCZIrw import czi


def main() -> None:
    root = Path("public-artifacts/pylibczirw")
    data = root / "pylibCZIrw/tests/integration/test_data"
    manifest = json.loads((data / "fixture_manifest.json").read_text())
    report = json.loads((data / "fixture_public_references.json").read_text())
    existing = {item["asset_id"]: item["subblocks"] for item in report["existing_assets"]}
    generated = {item["id"]: item["subblocks"] for item in report["generated_assets"]}
    results = []
    for asset in manifest["assets"]:
        if not asset["path"].endswith(".czi"):
            continue
        expected = existing[asset["id"]] if asset["id"] in existing else generated[asset["id"]]
        actual = []
        with czi.open_czi(str(root / asset["path"])) as reader:

            def collect(index, info):
                actual.append({"index": index, "coordinates": info.coordinate.to_dict(), "rect": [info.logicalRect.x, info.logicalRect.y, info.logicalRect.w, info.logicalRect.h], "stored_XY": [info.physicalSize.w, info.physicalSize.h]})
                return True

            reader.enumerate_subblocks(collect)
        assert len(actual) == len(expected)
        for ordinal, (native, reference) in enumerate(zip(actual, expected, strict=True)):
            coordinates = reference["coordinates"]
            assert native["index"] == ordinal
            assert native["coordinates"] == {axis: value for axis, value in coordinates.items() if axis not in {"X", "Y", "M"}}
            if "dimensions" in reference:
                spatial = {item["axis"]: item for item in reference["dimensions"] if item["axis"] in {"X", "Y"}}
                logical = [spatial[axis]["size"] for axis in ("X", "Y")]
                stored = [spatial[axis]["stored_size"] for axis in ("X", "Y")]
            else:
                stored = list(reversed(reference["shape_YX"]))
                logical = [int(size * Fraction(*reference["scale"][axis])) for axis, size in zip(("X", "Y"), stored, strict=True)]
            assert native["rect"] == [coordinates["X"], coordinates["Y"], *logical]
            assert native["stored_XY"] == stored
        results.append({"asset_id": asset["id"], "indices": [item["index"] for item in actual], "blocks": len(actual)})
    result = {"reader_source": czi.__file__, "files": len(results), "subblocks": sum(item["blocks"] for item in results), "checks": results, "limits": "Existing native enumeration agrees with the independent raw descriptor order/geometry; no new listing API or instrumented payload-I/O budget is tested."}
    (Path(__file__).parent / "native-indices.json").write_text(json.dumps(result, indent=2), encoding="utf8")
    print(json.dumps({key: result[key] for key in ("files", "subblocks", "limits")}))


if __name__ == "__main__":
    main()

